import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/changespillover/changespillover_2022_2023_waste.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

df_changes = pd.read_csv(DATASET_PATH)
df_adj = pd.read_csv(ADJACENCY_PATH)

borough_neighbors = {}
for index, row in df_adj.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in borough_neighbors:
        borough_neighbors[borough] = set()
    if neighbor not in borough_neighbors:
        borough_neighbors[neighbor] = set()
    borough_neighbors[borough].add(neighbor)
    borough_neighbors[neighbor].add(borough)

borough_to_delta = df_changes.set_index('borough')['delta_value'].to_dict()
boroughs = list(borough_to_delta.keys())
deltas = list(borough_to_delta.values())
mean_delta = np.mean(deltas)
z_dict = {borough: delta - mean_delta for borough, delta in borough_to_delta.items()}

spatial_lag_observed = {}
for borough in boroughs:
    neighbors = borough_neighbors.get(borough, set())
    if len(neighbors) == 0:
        spatial_lag_observed[borough] = 0.0
    else:
        neighbor_z = [z_dict[neighbor] for neighbor in neighbors if neighbor in z_dict]
        if len(neighbor_z) == 0:
            spatial_lag_observed[borough] = 0.0
        else:
            spatial_lag_observed[borough] = np.mean(neighbor_z)

numerator_observed = sum(z_dict[borough] * spatial_lag_observed[borough] for borough in boroughs)
denominator_observed = sum(z ** 2 for z in z_dict.values())
observed_I = numerator_observed / denominator_observed

permuted_Is = []
for _ in range(500):
    shuffled_deltas = np.random.permutation(deltas)
    shuffled_mapping = {borough: delta for borough, delta in zip(boroughs, shuffled_deltas)}
    mean_permuted = np.mean(shuffled_deltas)
    z_permuted = {borough: delta - mean_permuted for borough, delta in shuffled_mapping.items()}

    spatial_lag_permuted = {}
    for borough in boroughs:
        neighbors = borough_neighbors.get(borough, set())
        if len(neighbors) == 0:
            spatial_lag_permuted[borough] = 0.0
        else:
            neighbor_z_permuted = [z_permuted[neighbor] for neighbor in neighbors if neighbor in z_permuted]
            if len(neighbor_z_permuted) == 0:
                spatial_lag_permuted[borough] = 0.0
            else:
                spatial_lag_permuted[borough] = np.mean(neighbor_z_permuted)

    numerator_permuted = sum(z_permuted[borough] * spatial_lag_permuted[borough] for borough in boroughs)
    denominator_permuted = sum(z ** 2 for z in z_permuted.values())
    I_permuted = numerator_permuted / denominator_permuted
    permuted_Is.append(I_permuted)

p_value = sum(1 for I in permuted_Is if I >= observed_I) / len(permuted_Is)

print(f"Observed Moran's I: {observed_I}")
print(f"p-value: {p_value}")

if p_value < 0.05:
    print(f"FINAL ANSWER: CLUSTERED (statistical method = Global Moran's I, p = {p_value})")
else:
    print(f"FINAL ANSWER: NOT CLUSTERED (statistical method = Global Moran's I, p = {p_value})")
